  CREATE PROCEDURE [bud].[InsertBudgetFromHANA]  AS  BEGIN      SET NOCOUNT ON;        -- Only OIL has the DRAFT_APPROVAL procedure. Beverage/Mart do NOT (confirmed 31-08-2026).      DECLARE @companies TABLE (Branch NVARCHAR(10), SchemaName NVARCHAR(100));      INSERT INTO @companies (Branch, SchemaName) VALUES          ('OIL', 'JIVO_OIL_HANADB');        CREATE TABLE #TempBudgetData      (          Branch NVARCHAR(10), DocEntry INT, ObjectName NVARCHAR(50), ObjType INT,          LineNum INT, VisOrder INT, AcctCode NVARCHAR(50), AcctName NVARCHAR(255),          CardCode NVARCHAR(50), CardName NVARCHAR(255), EFFECTMONTH NVARCHAR(10),          BUDGET NVARCHAR(50), SUB_BUDGET NVARCHAR(50), STATE NVARCHAR(10),          DocDate DATETIME2, CreateDate DATETIME2, AMOUNT DECIMAL(18,2),          CURRENTMONTH NVARCHAR(10), Current_month_Posted_Amount DECIMAL(18,2),          Budget_Owner NVARCHAR(100), OwnerCode NVARCHAR(50), [Approver Name] NVARCHAR(100),          ApprovalCode NVARCHAR(50), Current_month_Budget NVARCHAR(50), [Status] NVARCHAR(10),          U_NAME NVARCHAR(100), CreatedDate DATETIME2, CreateTime NVARCHAR(50),          LineRemarks NVARCHAR(MAX), Comments NVARCHAR(MAX), ProcesStat NVARCHAR(10),          UpdateDate DATETIME2, OcrCode NVARCHAR(50), ACOMMENT NVARCHAR(MAX),          VCOMMENT NVARCHAR(MAX), VerifiedStatus NVARCHAR(10), ApprovedStatus NVARCHAR(10)      );        DECLARE @schemaName NVARCHAR(100), @cmd NVARCHAR(MAX);        DECLARE company_cursor CURSOR LOCAL FAST_FORWARD FOR          SELECT SchemaName FROM @companies;      OPEN company_cursor;      FETCH NEXT FROM company_cursor INTO @schemaName;        WHILE @@FETCH_STATUS = 0      BEGIN          BEGIN TRY              SET @cmd = 'CALL "' + @schemaName + '"."DRAFT_APPROVAL"';              INSERT INTO #TempBudgetData              EXEC (@cmd) AT HANADB112;          END TRY          BEGIN CATCH              INSERT INTO bud.jsSyncErrors (ErrorTime, ErrorMessage, ProcedureName, Query)              VALUES (GETDATE(),                      'InsertBudgetFromHANA pull failed for schema ' + @schemaName + ': ' + ERROR_MESSAGE(),                      'InsertBudgetFromHANA', @cmd);          END CATCH;            FETCH NEXT FROM company_cursor INTO @schemaName;      END      CLOSE company_cursor;      DEALLOCATE company_cursor;        INSERT INTO bud.jsBudgetTable      (          Branch, DocEntry, ObjectName, ObjType, LineNum, VisOrder, AcctCode, AcctName,          CardCode, CardName, EFFECTMONTH, BUDGET, SUB_BUDGET, STATE, DocDate, CreateDate,          AMOUNT, CURRENTMONTH, Current_month_Posted_Amount, Budget_Owner, OwnerCode,          [Approver Name], ApprovalCode, Current_month_Budget, [Status], U_NAME, CreatedDate,          CreateTime, LineRemarks, Comments, ProcesStat, UpdateDate, OcrCode, ACOMMENT,          VCOMMENT, VerifiedStatus, ApprovedStatus, [flag], budgetDate      )      SELECT          t.Branch, t.DocEntry, t.ObjectName, t.ObjType, t.LineNum, t.VisOrder, t.AcctCode,          t.AcctName, t.CardCode, t.CardName, t.EFFECTMONTH, t.BUDGET, t.SUB_BUDGET, t.STATE,          t.DocDate, t.CreateDate, t.AMOUNT, t.CURRENTMONTH, t.Current_month_Posted_Amount,          t.Budget_Owner, t.OwnerCode, t.[Approver Name], t.ApprovalCode, t.Current_month_Budget,          t.[Status], t.U_NAME, t.CreatedDate, t.CreateTime, t.LineRemarks, t.Comments,          t.ProcesStat, t.UpdateDate, t.OcrCode, t.ACOMMENT, t.VCOMMENT, t.VerifiedStatus,          t.ApprovedStatus, 'A' AS [flag], GETDATE() AS budgetDate      FROM #TempBudgetData t      WHERE NOT EXISTS      (          SELECT 1 FROM bud.jsBudgetTable b          WHERE b.Branch = t.Branch AND b.DocEntry = t.DocEntry AND b.ObjType = t.ObjType            AND b.LineNum = t.LineNum AND b.VisOrder = t.VisOrder      );        SELECT (SELECT COUNT(*) FROM #TempBudgetData) AS HanaRowsFetched,             @@ROWCOUNT AS SqlRowsInserted;        DROP TABLE #TempBudgetData;  END
